-- Explicit, membership-gated projections for the active Pages routes.
CREATE OR REPLACE FUNCTION public.hob_page(page_route text, requested_season integer DEFAULT NULL, requested_week integer DEFAULT NULL, requested_id integer DEFAULT NULL, requested_offset integer DEFAULT 0) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' SET extra_float_digits=3 AS $$
DECLARE page_result jsonb; y integer; w integer; page_offset integer;
BEGIN
 IF public.hob_viewer() IS NULL THEN RAISE EXCEPTION 'League membership required' USING ERRCODE='42501'; END IF;
 IF page_route LIKE 'admin%' AND public.hob_viewer()->>'role' IS DISTINCT FROM 'commissioner' THEN RAISE EXCEPTION 'Commissioner access required' USING ERRCODE='42501'; END IF;
 IF requested_season IS NOT NULL AND NOT EXISTS(SELECT 1 FROM hob_private.seasons WHERE season=requested_season) THEN RAISE EXCEPTION 'Season not found' USING ERRCODE='22023'; END IF;
 IF requested_week IS NOT NULL AND (requested_week<1 OR requested_week>25) THEN RAISE EXCEPTION 'Invalid week' USING ERRCODE='22023'; END IF;
 IF requested_offset IS NULL OR requested_offset<0 OR requested_offset>100000 THEN RAISE EXCEPTION 'Invalid offset' USING ERRCODE='22023'; END IF;
 page_offset:=requested_offset;
 y:=COALESCE(requested_season,(SELECT max(season) FROM hob_private.seasons));
 w:=COALESCE(requested_week,(SELECT min(week) FROM hob_private.matchups WHERE season=y AND NOT is_final),(SELECT max(week) FROM hob_private.matchups WHERE season=y),1);
 page_result:=jsonb_build_object('shell',public.hob_shell(),'season',y,'week',w,'seasons',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "season","status","team_count","reg_season_weeks" FROM hob_private."seasons" ORDER BY season DESC) r),'[]'::jsonb),'franchises',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","canonical_name","manager_name","joined_season","departed_season","active","accent_color" FROM hob_private."franchises" ORDER BY canonical_name) r),'[]'::jsonb),'teamSeasons',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","franchise_id","espn_team_id","team_name","abbrev","logo_url","division_id","wins","losses","ties","points_for","points_against","final_standing","made_playoffs" FROM hob_private."team_seasons" ) r),'[]'::jsonb));
 CASE page_route
 WHEN 'home' THEN page_result:=page_result || jsonb_build_object('matchups',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","espn_matchup_id","home_team_season_id","away_team_season_id","home_score","away_score","home_projected","away_projected","playoff_tier","multi_week_group","is_final","winner" FROM hob_private."matchups" WHERE season=y AND week=w ORDER BY id) r),'[]'::jsonb),'seasonStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","franchise_id","wins","losses","ties","points_for","points_against","allplay_w","allplay_l","allplay_t","luck_total","expected_wins","efficiency_avg","final_standing","made_playoffs","champion","sacko","beatdowns" FROM hob_private."season_stats" WHERE season=y) r),'[]'::jsonb),'careerStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","franchise_id","seasons","wins","losses","ties","win_pct","points_for","points_against","allplay_w","allplay_l","allplay_t","championships","sackos","playoff_appearances","best_finish","worst_finish","highest_week","highest_week_season","highest_week_week","lowest_week","lowest_week_season","lowest_week_week","longest_win_streak","longest_win_streak_start_season","longest_win_streak_start_week","longest_win_streak_end_season","longest_win_streak_end_week","longest_loss_streak","longest_loss_streak_start_season","longest_loss_streak_start_week","longest_loss_streak_end_season","longest_loss_streak_end_week","current_elo","peak_elo","luck_total","expected_wins","efficiency_avg","beatdowns","worst_beatdown_margin","worst_beatdown_season","worst_beatdown_week" FROM hob_private."career_stats" ) r),'[]'::jsonb),'beltReigns',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","reign_no","franchise_id","won_from_franchise_id","start_season","start_week","end_season","end_week","defenses","weeks_held","end_reason","is_current" FROM hob_private."belt_reigns" WHERE is_current) r),'[]'::jsonb),'records',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","record_key","rank","franchise_id","season","week","value","week_type","detail_json" FROM hob_private."record_entries" WHERE rank=1) r),'[]'::jsonb),'recaps',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","style","status","markdown_final","created_at" FROM hob_private."recaps" WHERE status='published' ORDER BY season DESC,week DESC,id DESC LIMIT 1) r),'[]'::jsonb));
 WHEN 'matchups' THEN page_result:=page_result || jsonb_build_object('weeks',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "season","week","scoring_period_id","week_type","is_complete" FROM hob_private."weeks" WHERE season=y ORDER BY week) r),'[]'::jsonb),'matchups',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","espn_matchup_id","home_team_season_id","away_team_season_id","home_score","away_score","home_projected","away_projected","playoff_tier","multi_week_group","is_final","winner" FROM hob_private."matchups" WHERE season=y AND week=w AND (requested_id IS NULL OR id=requested_id) ORDER BY id) r),'[]'::jsonb),'rosterSlots',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","team_season_id","player_id","lineup_slot","is_starter","points","projected_points","eligible_slots_json" FROM hob_private."roster_slots" WHERE requested_id IS NOT NULL AND season=y AND week=w AND team_season_id IN (SELECT home_team_season_id FROM hob_private.matchups WHERE id=requested_id AND season=y AND week=w UNION SELECT away_team_season_id FROM hob_private.matchups WHERE id=requested_id AND season=y AND week=w)) r),'[]'::jsonb),'players',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "espn_player_id","full_name","default_position","pro_team","headshot_url" FROM hob_private."players" WHERE requested_id IS NOT NULL AND espn_player_id IN (SELECT player_id FROM hob_private.roster_slots WHERE season=y AND week=w)) r),'[]'::jsonb),'teamWeek',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","week","week_type","team_season_id","franchise_id","opponent_franchise_id","matchup_id","score","projected","result","margin","optimal_score","bench_points_left","efficiency","eligibility_fallback" FROM hob_private."team_week" WHERE season=y AND week=w) r),'[]'::jsonb),'contextNotes',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","subject_type","season","week","franchise_id","matchup_id","rule_id","salience","rendered_text","facts_json" FROM hob_private."context_notes" WHERE season=y AND week=w) r),'[]'::jsonb),'beltMatches',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","matchup_id","season","week","holder_franchise_id","challenger_franchise_id","result","holder_score","challenger_score" FROM hob_private."belt_matches" WHERE season=y AND week=w) r),'[]'::jsonb));
 WHEN 'history' THEN page_result:=page_result || '{}'::jsonb;
 WHEN 'franchises' THEN page_result:=page_result || jsonb_build_object('careerStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","franchise_id","seasons","wins","losses","ties","win_pct","points_for","points_against","allplay_w","allplay_l","allplay_t","championships","sackos","playoff_appearances","best_finish","worst_finish","highest_week","highest_week_season","highest_week_week","lowest_week","lowest_week_season","lowest_week_week","longest_win_streak","longest_win_streak_start_season","longest_win_streak_start_week","longest_win_streak_end_season","longest_win_streak_end_week","longest_loss_streak","longest_loss_streak_start_season","longest_loss_streak_start_week","longest_loss_streak_end_season","longest_loss_streak_end_week","current_elo","peak_elo","luck_total","expected_wins","efficiency_avg","beatdowns","worst_beatdown_margin","worst_beatdown_season","worst_beatdown_week" FROM hob_private."career_stats" WHERE requested_id IS NULL OR franchise_id=requested_id) r),'[]'::jsonb),'seasonStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","franchise_id","wins","losses","ties","points_for","points_against","allplay_w","allplay_l","allplay_t","luck_total","expected_wins","efficiency_avg","final_standing","made_playoffs","champion","sacko","beatdowns" FROM hob_private."season_stats" WHERE franchise_id=requested_id ORDER BY season DESC) r),'[]'::jsonb),'eloHistory',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","week","franchise_id","elo_pre","elo_post" FROM hob_private."elo_history" WHERE franchise_id=requested_id ORDER BY season,week) r),'[]'::jsonb),'beltReigns',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","reign_no","franchise_id","won_from_franchise_id","start_season","start_week","end_season","end_week","defenses","weeks_held","end_reason","is_current" FROM hob_private."belt_reigns" WHERE franchise_id=requested_id ORDER BY reign_no DESC) r),'[]'::jsonb),'records',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","record_key","rank","franchise_id","season","week","value","week_type","detail_json" FROM hob_private."record_entries" WHERE franchise_id=requested_id ORDER BY record_key,rank) r),'[]'::jsonb),'achievements',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","achievement_key","franchise_id","season","week","dedupe_key","payload_json" FROM hob_private."achievements" WHERE franchise_id=requested_id ORDER BY season DESC,week DESC) r),'[]'::jsonb),'h2hPairs',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","franchise_a","franchise_b","reg_w","reg_l","reg_t","playoff_w","playoff_l","playoff_t","points_a","points_b","avg_margin","streak_holder","streak_len","largest_win_json","closest_game_json","last_meeting_json" FROM hob_private."h2h_pairs" WHERE franchise_a=requested_id OR franchise_b=requested_id) r),'[]'::jsonb));
 WHEN 'h2h' THEN page_result:=page_result || jsonb_build_object('h2hPairs',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","franchise_a","franchise_b","reg_w","reg_l","reg_t","playoff_w","playoff_l","playoff_t","points_a","points_b","avg_margin","streak_holder","streak_len","largest_win_json","closest_game_json","last_meeting_json" FROM hob_private."h2h_pairs" ) r),'[]'::jsonb),'matchups',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","espn_matchup_id","home_team_season_id","away_team_season_id","home_score","away_score","home_projected","away_projected","playoff_tier","multi_week_group","is_final","winner" FROM hob_private."matchups" WHERE requested_id IS NOT NULL AND is_final AND (home_team_season_id IN (SELECT id FROM hob_private.team_seasons WHERE franchise_id=requested_id) OR away_team_season_id IN (SELECT id FROM hob_private.team_seasons WHERE franchise_id=requested_id)) ORDER BY season DESC,week DESC) r),'[]'::jsonb));
 WHEN 'seasons' THEN page_result:=page_result || jsonb_build_object('seasonStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","franchise_id","wins","losses","ties","points_for","points_against","allplay_w","allplay_l","allplay_t","luck_total","expected_wins","efficiency_avg","final_standing","made_playoffs","champion","sacko","beatdowns" FROM hob_private."season_stats" WHERE requested_season IS NULL OR season=y ORDER BY season DESC,final_standing NULLS LAST) r),'[]'::jsonb),'weeks',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "season","week","scoring_period_id","week_type","is_complete" FROM hob_private."weeks" WHERE season=y ORDER BY week) r),'[]'::jsonb),'matchups',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","espn_matchup_id","home_team_season_id","away_team_season_id","home_score","away_score","home_projected","away_projected","playoff_tier","multi_week_group","is_final","winner" FROM hob_private."matchups" WHERE requested_season IS NOT NULL AND season=y ORDER BY week,id) r),'[]'::jsonb),'draftPicks',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","round","round_pick","overall_pick","team_season_id","player_id","keeper","auction_amount" FROM hob_private."draft_picks" WHERE requested_season IS NOT NULL AND season=y ORDER BY overall_pick) r),'[]'::jsonb),'players',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "espn_player_id","full_name","default_position","pro_team","headshot_url" FROM hob_private."players" WHERE espn_player_id IN (SELECT player_id FROM hob_private.draft_picks WHERE season=y)) r),'[]'::jsonb));
 WHEN 'records' THEN page_result:=page_result || jsonb_build_object('records',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","record_key","rank","franchise_id","season","week","value","week_type","detail_json" FROM hob_private."record_entries" ORDER BY record_key,rank) r),'[]'::jsonb));
 WHEN 'belt' THEN page_result:=page_result || jsonb_build_object('beltReigns',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","reign_no","franchise_id","won_from_franchise_id","start_season","start_week","end_season","end_week","defenses","weeks_held","end_reason","is_current" FROM hob_private."belt_reigns" ORDER BY reign_no DESC) r),'[]'::jsonb),'beltMatches',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","matchup_id","season","week","holder_franchise_id","challenger_franchise_id","result","holder_score","challenger_score" FROM hob_private."belt_matches" ORDER BY season DESC,week DESC) r),'[]'::jsonb));
 WHEN 'timeline' THEN page_result:=page_result || jsonb_build_object('seasonStats',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","franchise_id","wins","losses","ties","points_for","points_against","allplay_w","allplay_l","allplay_t","luck_total","expected_wins","efficiency_avg","final_standing","made_playoffs","champion","sacko","beatdowns" FROM hob_private."season_stats" ) r),'[]'::jsonb),'beltReigns',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","reign_no","franchise_id","won_from_franchise_id","start_season","start_week","end_season","end_week","defenses","weeks_held","end_reason","is_current" FROM hob_private."belt_reigns" ) r),'[]'::jsonb),'records',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","record_key","rank","franchise_id","season","week","value","week_type","detail_json" FROM hob_private."record_entries" WHERE rank=1) r),'[]'::jsonb));
 WHEN 'transactions' THEN page_result:=page_result || jsonb_build_object('transactions',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","type","status","bid_amount","proposed_at","processed_at" FROM hob_private."transactions" WHERE season=y ORDER BY processed_at DESC NULLS LAST,id DESC LIMIT 100 OFFSET page_offset) r),'[]'::jsonb),'transactionItems',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","transaction_id","team_season_id","player_id","action","source" FROM hob_private."transaction_items" WHERE transaction_id IN (SELECT id FROM hob_private.transactions WHERE season=y ORDER BY processed_at DESC NULLS LAST,id DESC LIMIT 100 OFFSET page_offset)) r),'[]'::jsonb),'players',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "espn_player_id","full_name","default_position","pro_team","headshot_url" FROM hob_private."players" WHERE espn_player_id IN (SELECT player_id FROM hob_private.transaction_items WHERE transaction_id IN (SELECT id FROM hob_private.transactions WHERE season=y ORDER BY processed_at DESC NULLS LAST,id DESC LIMIT 100 OFFSET page_offset))) r),'[]'::jsonb));
 WHEN 'what-if' THEN page_result:=page_result || jsonb_build_object('teamWeek',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","build_id","season","week","week_type","team_season_id","franchise_id","opponent_franchise_id","matchup_id","score","projected","result","margin","optimal_score","bench_points_left","efficiency","eligibility_fallback" FROM hob_private."team_week" WHERE season=y ORDER BY week) r),'[]'::jsonb));
 WHEN 'recaps' THEN page_result:=page_result || jsonb_build_object('recaps',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","style","status","markdown_final","created_at" FROM hob_private."recaps" WHERE status='published' AND id IN (SELECT max(id) FROM hob_private.recaps WHERE status='published' GROUP BY season,week) AND (requested_season IS NULL OR season=y) AND (requested_week IS NULL OR week=w) ORDER BY season DESC,week DESC,id DESC) r),'[]'::jsonb));
 WHEN 'admin' THEN page_result:=page_result || jsonb_build_object('managers',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","name","role","franchise_id","created_at" FROM hob_private."managers" ORDER BY name) r),'[]'::jsonb),'memberships',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "manager_id","revoked_at" FROM hob_private."memberships" ) r),'[]'::jsonb),'syncRuns',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","started_at","finished_at","tier","status","views_fetched","snapshots_new" FROM hob_private."sync_runs" ORDER BY id DESC LIMIT 10) r),'[]'::jsonb),'statBuilds',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","started_at","finished_at","status","duration_ms" FROM hob_private."stat_builds" ORDER BY id DESC LIMIT 5) r),'[]'::jsonb),'settings',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "key","value_json" FROM hob_private."app_settings" WHERE key IN ('draft_date','recap_voice_notes')) r),'[]'::jsonb));
 WHEN 'admin-recaps' THEN page_result:=page_result || jsonb_build_object('recaps',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "id","season","week","style","status","markdown_final","created_at","markdown_draft" FROM hob_private."recaps" WHERE requested_id IS NULL OR id=requested_id ORDER BY season DESC,week DESC,id DESC) r),'[]'::jsonb),'settings',COALESCE((SELECT jsonb_agg(r) FROM (SELECT "key","value_json" FROM hob_private."app_settings" WHERE key='recap_voice_notes') r),'[]'::jsonb));
 ELSE RAISE EXCEPTION 'Page not found' USING ERRCODE='22023';
 END CASE;
 RETURN page_result;
END $$;
REVOKE ALL ON FUNCTION public.hob_page(text,integer,integer,integer,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hob_page(text,integer,integer,integer,integer) TO authenticated;
